-- Adds Launchpad's sample posts to the live project (Lama, 2026-10-26): the seed's events, office hours and tips
-- (supabase/seed.sql, from data/fixtures/hub.ts), so the demo has something to RSVP to and office hours to book. Only
-- the posts: no RSVPs or slot requests.
--
-- Run once in the dashboard's SQL editor, as postgres. Safe to run again: a post whose id is already there is left as
-- it is. A post written by Naledi (the sample mentor) keeps her as its author only if her profile is there
-- (add-demo-accounts.sql); otherwise it has no author and shows as the Hub's. The last statement lists the posts
-- still to come, soonest first.
--
-- The clear-out (clear-sample-data.sql) removes them with the rest of the sample data.
begin;

create temp table demo_hub_posts on commit drop as select id, kind, title, summary, place, body, campus_slug, starts_at, capacity, going, image_src, image_alt, published, published_at, author_id, created_at, updated_at from public.hub_posts limit 0;


select d.id, d.kind, d.title, d.summary, d.place, d.body, d.campus_slug, d.starts_at, d.capacity, d.going, d.image_src, d.image_alt, d.published, d.published_at, (select p.id from public.profiles p where p.id = d.author_id) as author_id, d.created_at, d.updated_at
from demo_hub_posts d
on conflict (id) do nothing;

commit;

select id, kind, title, coalesce(campus_slug, 'every campus') as campus, starts_at
from public.hub_posts
where published and (starts_at is null or starts_at >= now())
order by starts_at nulls last, published_at desc;
